  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In rats, [18F]MPPF brain uptake was only 0.05% ID/g at 30 min and the compound is a P-gp substrate, indicating impermeable BBB access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In rats, [11C]6 showed low baseline brain uptake that increased dramatically after cyclosporin A pretreatment, demonstrating ABC-transporter-mediated exclusion from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy humans, bepotastine produced only 16.6% cortical H1 receptor occupancy by PET after nighttime dosing, consistent with slight/limited BBB penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred records consistently indicate poor or impermeable BBB access across species and assay types, including low brain uptake, efflux-mediated exclusion, and low human CNS receptor occupancy; meaningful CNS access is not supported.",
  "evidence_gaps": [
    "Most records are qualitative impermeable-BBB labels or radiotracer uptake measures; quantitative therapeutic-dose CNS exposure data are limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

